const fs = require('node:fs');
const path = require('node:path');
const root = './work/main/claude-haiku-5-5/09db27f10adf';
const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith('.js')) files.push(p);
  }
}
walk(path.join(root, 'src'));
walk(path.join(root, 'test'));
let renamed = 0, retained = 0, changedFiles = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  let out = src.replace(/\bretryPolicy\b/g, () => { renamed++; return 'backoffPolicy'; });
  out = out.replace(/\bmaxAttempts: 3\b/g, () => { retained++; return 'maxAttempts: 5'; });
  if (out !== src) { fs.writeFileSync(f, out); changedFiles++; }
}
const left = await $`grep -rn "retryPolicy" ${root}/src ${root}/test`;
const test = await $`cd ${root} && node --test 2>&1`;
return { filesScanned: files.length, changedFiles, identifiersRenamed: renamed, maxAttemptsChanged: retained, leftoverRetryPolicy: left.stdout.trim(), testExit: test.exitCode, testOutput: test.stdout.slice(-3000) };

